#include <stdio.h>
int heap[100],sz=0;
void push(int v){heap[sz++]=v;int i=sz-1;while(i>0){int p=(i-1)/2;if(heap[p]>heap[i]){int t=heap[p];heap[p]=heap[i];heap[i]=t;i=p;}else break;}}
int pop(){int m=heap[0];heap[0]=heap[--sz];int i=0;while(1){int l=2*i+1,r=2*i+2,s=i;if(l<sz&&heap[l]<heap[s])s=l;if(r<sz&&heap[r]<heap[s])s=r;if(s==i)break;int t=heap[i];heap[i]=heap[s];heap[s]=t;i=s;}return m;}
int main(){push(5);push(1);push(3);push(9);push(2);while(sz)printf("%d ",pop());return 0;}
